"use client";

import { useEffect, useState } from "react";
import { useRouter } from "next/navigation";
import { useI18n } from "@/i18n/context";
import PrinterLoader from "@/components/PrinterLoader";
import SearchInput, { matchesQuery } from "@/components/SearchInput";
import { apiErrorMessage } from "@/lib/api-client";
import { AddFormBoundary, useAutoAddForm } from "@/hooks/useAutoAddForm";
import { useToast, useConfirm } from "@/components/UIProvider";
import { FileText, Pencil, Plus, Save, Trash2 } from "lucide-react";
import FormModal from "@/components/FormModal";
import SubmitButton from "@/components/SubmitButton";

interface CompanyData {
  id: string;
  name: string;
  nameAr: string | null;
  taxNumber?: string | null;
  tradeRegister?: string | null;
  address?: string | null;
  phone?: string | null;
  email?: string | null;
  totalSales: number;
  totalPurchases: number;
  totalExpenses: number;
  salesReturns: number;
  purchaseReturns: number;
  totalSettlements: number;
  netProfit: number;
  counts: {
    salesOrders: number;
    purchaseOrders: number;
  };
}

const COMPANY_ICONS: Record<string, string> = {
  "╪┤╪▒┘â╪⌐ ╪¼┘à┘ä╪⌐ ╪ó┘ä╪º╪¬": "≡ƒû¿∩╕Å",
  "╪┤╪▒┘â╪⌐ ╪¼┘à┘ä╪⌐ ┘é╪╖╪╣ ╪║┘è╪º╪▒": "≡ƒöº",
  "╪┤╪▒┘â╪⌐ ╪º┘ä┘é╪╖╪º╪╣┘è": "ΓÜí",
};

const emptyForm = {
  name: "",
  nameAr: "",
  taxNumber: "",
  tradeRegister: "",
  address: "",
  phone: "",
  email: "",
};

export default function CompaniesPage() {
  const { t, dir } = useI18n();
  const router = useRouter();

  const [companies, setCompanies] = useState<CompanyData[]>([]);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState("");
  const [showForm, setShowForm] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [form, setForm] = useState(emptyForm);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState("");
  const { success: toastSuccess, error: toastError } = useToast();
  const confirmAction = useConfirm();

  const fetchCompanies = () => {
    fetch("/api/companies")
      .then((r) => r.json())
      .then((data) => {
        setCompanies(Array.isArray(data) ? data : []);
        setLoading(false);
      })
      .catch(() => setLoading(false));
  };

  useEffect(() => {
    fetchCompanies();
  }, []);

  const autoAddOpen = useAutoAddForm();
  useEffect(() => {
    if (autoAddOpen) setShowForm(true);
  }, [autoAddOpen]);

  const totalSales = companies.reduce((s, c) => s + c.totalSales, 0);
  const totalPurchases = companies.reduce((s, c) => s + c.totalPurchases, 0);
  const totalExpenses = companies.reduce((s, c) => s + (c.totalExpenses || 0), 0);
  const totalNetProfit = companies.reduce((s, c) => s + c.netProfit, 0);

  const filtered = companies.filter((c) =>
    matchesQuery(c.name, search) ||
    (Boolean(c.nameAr) && matchesQuery(c.nameAr || "", search))
  );

  const openCreate = () => {
    setForm(emptyForm);
    setEditingId(null);
    setError("");
    setShowForm(!showForm);
  };

  const openEdit = (company: CompanyData) => {
    setForm({
      name: company.name,
      nameAr: company.nameAr || "",
      taxNumber: company.taxNumber || "",
      tradeRegister: company.tradeRegister || "",
      address: company.address || "",
      phone: company.phone || "",
      email: company.email || "",
    });
    setEditingId(company.id);
    setError("");
    setShowForm(true);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setSaving(true);
    setError("");
    try {
      const res = await fetch(editingId ? `/api/companies/${editingId}` : "/api/companies", {
        method: editingId ? "PUT" : "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(form),
      });
      const data = await res.json().catch(() => null);
      if (!res.ok) {
        setError(apiErrorMessage(data, t));
        return;
      }
      setShowForm(false);
      setForm(emptyForm);
      setEditingId(null);
      fetchCompanies();
      toastSuccess(t("common.savedSuccessfully"));
    } finally {
      setSaving(false);
    }
  };

  const handleDelete = async (id: string) => {
    if (!(await confirmAction({ message: t("companies.deleteConfirm") }))) return;
    const res = await fetch(`/api/companies/${id}`, { method: "DELETE" });
    const data = await res.json().catch(() => null);
    if (!res.ok) {
      toastError(apiErrorMessage(data, t));
      return;
    }
    fetchCompanies();
    toastSuccess(t("common.deletedSuccessfully"));
  };

  if (loading) {
    return (
      <div dir={dir} className="flex min-h-[50vh] items-center justify-center px-4">
        <PrinterLoader size="md" label={t("common.loading")} />
      </div>
