        customersRes.json(),
        companiesRes.json(),
      ]);
      setCustomers(customersData);
      setCompanies(Array.isArray(companiesData) ? companiesData : []);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchCustomers();
