"use client";

import { useEffect, useState } from "react";
import Link from "next/link";
import { AddFormBoundary, useAutoAddForm } from "@/hooks/useAutoAddForm";
import { useSession } from "next-auth/react";
import { useI18n } from "@/i18n/context";
import Pagination from "@/components/Pagination";
import SearchInput, { matchesQuery } from "@/components/SearchInput";
import FilterSelect from "@/components/FilterSelect";
import { Save, Trash2, X } from "lucide-react";
import DateRangeFilter, { inDateRange } from "@/components/DateRangeFilter";
import ExportButton from "@/components/ExportButton";
import PrinterLoader from "@/components/PrinterLoader";
import { DateTimeCell } from "@/components/DateTimeCell";
import { useUrlParams, useSearchWithDefault } from "@/hooks/useUrlParams";
import FormModal from "@/components/FormModal";
import SelectWithAdd from "@/components/SelectWithAdd";
import { useConfirm, useToast } from "@/components/UIProvider";
import { apiErrorMessage } from "@/lib/api-client";
import SubmitButton from "@/components/SubmitButton";

const PRIORITY_LABELS: Record<string, string> = {
  NORMAL: "╪╣╪º╪»┘è",
  IMPORTANT: "┘à┘ç┘à",
  URGENT: "╪╣╪º╪¼┘ä",
  EMERGENCY: "╪╖╪º╪▒╪ª",
};

const STATUS_LABELS: Record<string, string> = {
  NEW: "╪¼╪»┘è╪»",
  ASSIGNED: "╪¬┘à ╪º┘ä╪¬╪╣┘è┘è┘å",
  VISITED: "╪¬┘à╪¬ ╪º┘ä╪▓┘è╪º╪▒╪⌐",
  RESOLVED: "╪¬┘à ╪º┘ä╪¡┘ä",
  NOT_RESOLVED: "┘ä┘à ┘è╪¬┘à ╪º┘ä╪¡┘ä",
  REASSIGNED: "╪Ñ╪╣╪º╪»╪⌐ ╪º┘ä╪¬╪╣┘è┘è┘å",
  CLOSED: "┘à╪║┘ä┘é",
};

interface Customer { id: string; name: string; locations?: Location[]; }
interface Engineer { id: string; name: string; user?: { id?: string | null } | null; userId?: string | null; }
interface Machine { id: string; serialNumber: string; model?: string | null; currentOwnerId?: string | null; customerLocationId?: string | null; }
interface Location { id: string; name: string; }
interface ProblemDetail { id: string; description: string; }

interface ServiceRequest {
  id: string;
  requestNumber: string;
  customerId: string;
  locationId: string | null;
  machineId: string | null;
  description: string;
  priority: string;
  status: string;
  engineerId: string | null;
  customerRating: number | null;
  ratingNotes: string | null;
  createdAt: string;
  customer: Customer;
  location: Location | null;
  machine: Machine | null;
  engineer: Engineer | null;
  problems: ProblemDetail[];
}

const priorityColors: Record<string, string> = {
  NORMAL: "bg-gray-100 text-gray-800",
  IMPORTANT: "bg-yellow-100 text-yellow-800",
  URGENT: "bg-orange-100 text-orange-800",
  EMERGENCY: "bg-red-100 text-red-800",
};

const statusColors: Record<string, string> = {
  NEW: "bg-blue-100 text-blue-800",
  ASSIGNED: "bg-purple-100 text-purple-800",
  VISITED: "bg-yellow-100 text-yellow-800",
  RESOLVED: "bg-green-100 text-green-800",
  NOT_RESOLVED: "bg-red-100 text-red-800",
  REASSIGNED: "bg-indigo-100 text-indigo-800",
  CLOSED: "bg-gray-100 text-gray-800",
};

export default function ServiceRequestsPage() {
  const { t, dir } = useI18n();
  const { data: session } = useSession();
  const userRole = (session?.user as { role?: string } | undefined)?.role;
  const isEngineer = userRole === "ENGINEER";
  const canManageRequests = ["GENERAL_MANAGER", "COMPANY_MANAGER", "MAINTENANCE_MANAGER", "WORKSHOP_MANAGER"].includes(userRole ?? "");
  const confirmAction = useConfirm();
  const { success: toastSuccess, error: toastError } = useToast();
  const [requests, setRequests] = useState<ServiceRequest[]>([]);
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [engineers, setEngineers] = useState<Engineer[]>([]);
  const myEngineerId = engineers.find((engineer) => engineer.user?.id === session?.user?.id || engineer.userId === session?.user?.id)?.id ?? null;
  const [machines, setMachines] = useState<Machine[]>([]);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [showForm, setShowForm] = useState(false);
  const [assigningId, setAssigningId] = useState<string | null>(null);
  const [assignEngineerId, setAssignEngineerId] = useState("");
  const urlParams = useUrlParams(["focus"]);
  const focusedRequest = urlParams.focus ? requests.find((r) => r.id === urlParams.focus) : undefined;
  const [search, setSearchInput] = useSearchWithDefault(focusedRequest?.requestNumber ?? "");
  const [statusFilter, setStatusFilter] = useState("");
  const [priorityFilter, setPriorityFilter] = useState("");
  const [engineerFilter, setEngineerFilter] = useState("");
  const [dateFrom, setDateFrom] = useState("");
  const [dateTo, setDateTo] = useState("");
  const [form, setForm] = useState({
    customerId: "",
    locationId: "",
    machineId: "",
    description: "",
    priority: "NORMAL",
  });
  const [page, setPage] = useState(1);
  const PAGE_SIZE = 15;

  const fetchData = async () => {
    try {
      const [reqRes, custRes, engRes, machineRes] = await Promise.all([
        fetch("/api/service-requests"),
        fetch("/api/customers"),
        fetch("/api/engineers"),
        fetch("/api/machines"),
      ]);
      setRequests(await reqRes.json());
      setCustomers(await custRes.json());
      setEngineers(await engRes.json());
      setMachines(await machineRes.json());
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => { fetchData(); }, []);

  const autoAddOpen = useAutoAddForm();
  useEffect(() => {
    if (autoAddOpen) setShowForm(true);
  }, [autoAddOpen]);

  const handleCreate = async (e: React.FormEvent) => {
    e.preventDefault();
    setSaving(true);
    await fetch("/api/service-requests", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        ...form,
        locationId: form.locationId || undefined,
        machineId: form.machineId || undefined,
      }),
    });
    setSaving(false);
    setForm({ customerId: "", locationId: "", machineId: "", description: "", priority: "NORMAL" });
    setShowForm(false);
    fetchData();
  };

  const handleAssign = async (id: string) => {
    await fetch(`/api/service-requests/${id}`, {
      method: "PUT",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ engineerId: assignEngineerId, status: "ASSIGNED" }),
    });
    setAssigningId(null);
    setAssignEngineerId("");
    fetchData();
  };

  const handleStatus = async (id: string, status: string) => {
    await fetch(`/api/service-requests/${id}`, {
      method: "PUT",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ status }),
    });
    fetchData();
  };

  const handleDelete = async (id: string) => {
    if (!(await confirmAction({ message: t("common.deleteConfirm") }))) return;
    const res = await fetch(`/api/service-requests/${id}`, { method: "DELETE" });
    const data = await res.json().catch(() => null);
    if (!res.ok) { toastError(apiErrorMessage(data, t)); return; }
    fetchData();
    toastSuccess(t("common.deletedSuccessfully"));
  };

  const renderStars = (rating: number | null) => {
    if (rating === null) return null;
    return (
      <span className="text-yellow-500">
        {"Γÿà".repeat(rating)}{"Γÿå".repeat(5 - rating)}
      </span>
    );
  };

  const filtered = requests.filter((request) => {
    if (isEngineer && myEngineerId && request.engineerId !== myEngineerId) {
      return false;
    }
    if (isEngineer && !myEngineerId) {
      return false;
    }

    return (
      (!statusFilter || request.status === statusFilter) &&
      (!priorityFilter || request.priority === priorityFilter) &&
      (!engineerFilter || request.engineerId === engineerFilter) &&
      inDateRange(request.createdAt, dateFrom, dateTo) &&
      (matchesQuery(request.requestNumber, search) ||
        matchesQuery(request.description, search) ||
        matchesQuery(request.customer?.name, search) ||
        matchesQuery(request.machine?.serialNumber, search) ||
        matchesQuery(request.engineer?.name, search))
    );
  });
  const hasActiveFilters = statusFilter !== "" || priorityFilter !== "" || (!isEngineer && engineerFilter !== "") || dateFrom !== "" || dateTo !== "" || search !== "";
  const totalPages = Math.max(1, Math.ceil(filtered.length / PAGE_SIZE));
  const safePage = Math.min(page, totalPages);
  const paged = filtered.slice((safePage - 1) * PAGE_SIZE, safePage * PAGE_SIZE);

  const exportRequests = () => ({
    headers: [
      t("serviceRequests.requestNumber"),
      t("serviceRequests.customer"),
      t("serviceRequests.machine"),
      t("serviceRequests.priority"),
      t("serviceRequests.status"),
      t("serviceRequests.engineer"),
      t("common.date"),
      t("serviceRequests.problems"),
      t("serviceRequests.rating"),
    ],
    rows: filtered.map((req) => [
      req.requestNumber,
      req.customer.name,
      req.machine?.serialNumber || "",
      PRIORITY_LABELS[req.priority] || req.priority,
      STATUS_LABELS[req.status] || req.status,
      req.engineer?.name || "",
      new Date(req.createdAt).toISOString().slice(0, 10),
      String(req.problems.length),
      req.customerRating != null ? String(req.customerRating) : "",
    ]),
  });

  const inputClass = "w-full rounded-lg border border-gray-300 px-3 py-2.5 text-sm focus:border-blue-500 focus:outline-none focus:ring-2 focus:ring-blue-500";

  return (
    <div dir={dir} className="space-y-5">
      <AddFormBoundary />
      <div className="flex flex-col gap-3 rounded-2xl border border-slate-200 bg-white p-5 shadow-sm sm:flex-row sm:items-center sm:justify-between">
        <div>
          <p className="text-xs font-medium tracking-[0.2em] text-sky-600 uppercase">ERP</p>
          <h1 className="mt-1 text-xl font-bold text-slate-900 sm:text-2xl lg:text-3xl">{t("serviceRequests.title")}</h1>
        </div>
        {canManageRequests && (
          <button onClick={() => setShowForm(true)} className="inline-flex items-center justify-center gap-2 rounded-xl bg-sky-600 px-4 py-2.5 text-sm font-semibold text-white shadow-sm transition hover:bg-sky-700">
            <span className="text-lg leading-none">+</span>{t("serviceRequests.newRequest")}
          </button>
        )}
      </div>

      <FormModal open={showForm} onClose={() => setShowForm(false)} title={t("serviceRequests.newRequest")}>
        <form onSubmit={handleCreate} className="space-y-4">
          <SelectWithAdd
            label={t("serviceRequests.selectCustomer")}
            value={form.customerId}
            onChange={(v) => setForm({ ...form, customerId: v, locationId: "", machineId: "" })}
            options={customers.map((c) => ({ value: c.id, label: c.name }))}
            placeholder={t("serviceRequests.selectCustomer")}
            required
            quickAddTitle="╪Ñ╪╢╪º┘ü╪⌐ ╪╣┘à┘è┘ä ╪¼╪»┘è╪»"
            quickAddFields={[
              { key: "name", label: "╪º╪│┘à ╪º┘ä╪╣┘à┘è┘ä", required: true },
              { key: "phone", label: "╪º┘ä┘ç╪º╪¬┘ü", placeholder: "01xxxxxxxxx" },
              { key: "companyName", label: "╪º╪│┘à ╪º┘ä╪┤╪▒┘â╪⌐" },
              { key: "email", label: "╪º┘ä╪¿╪▒┘è╪» ╪º┘ä╪Ñ┘ä┘â╪¬╪▒┘ê┘å┘è", type: "email" },
              { key: "address", label: "╪º┘ä╪╣┘å┘ê╪º┘å" },
              { key: "city", label: "╪º┘ä┘à╪»┘è┘å╪⌐" },
              { key: "customerType", label: "┘å┘ê╪╣ ╪º┘ä╪╣┘à┘è┘ä", type: "select", options: [{ value: "INDIVIDUAL", label: "┘ü╪▒╪»" }, { value: "COMPANY", label: "╪┤╪▒┘â╪⌐" }] },
              { key: "whatsapp", label: "┘ê╪º╪¬╪│╪º╪¿" },
            ]}
            quickAddEndpoint="/api/customers"
            onQuickAddSuccess={(item) => {
              setCustomers((prev) => [...prev, item]);
              setForm((f) => ({ ...f, customerId: item.id, locationId: "", machineId: "" }));
            }}
          />
          <div className="space-y-1.5">
            <label className="block text-sm font-medium text-slate-700">{t("machineDetails.location")}</label>
            <select value={form.locationId} onChange={(e) => setForm({ ...form, locationId: e.target.value, machineId: "" })} className={inputClass}>
              <option value="">{t("common.selectOption")}</option>
              {customers.find(customer => customer.id === form.customerId)?.locations?.map(location => <option key={location.id} value={location.id}>{location.name}</option>)}
            </select>
          </div>
          <div className="space-y-1.5">
            <label className="block text-sm font-medium text-slate-700">{t("serviceRequests.machine")}</label>
            <select value={form.machineId} onChange={(e) => setForm({ ...form, machineId: e.target.value })} className={inputClass}>
              <option value="">{t("common.selectOption")}</option>
              {machines.filter(machine => machine.currentOwnerId === form.customerId && (!form.locationId || machine.customerLocationId === form.locationId)).map(machine => <option key={machine.id} value={machine.id}>{machine.serialNumber}{machine.model ? ` ┬╖ ${machine.model}` : ""}</option>)}
            </select>
          </div>
          <div className="space-y-1.5">
            <label className="block text-sm font-medium text-slate-700">{t("serviceRequests.priority")}</label>
            <select value={form.priority} onChange={(e) => setForm({ ...form, priority: e.target.value })} className={inputClass}>
              <option value="NORMAL">{PRIORITY_LABELS.NORMAL}</option>
              <option value="IMPORTANT">{PRIORITY_LABELS.IMPORTANT}</option>
              <option value="URGENT">{PRIORITY_LABELS.URGENT}</option>
              <option value="EMERGENCY">{PRIORITY_LABELS.EMERGENCY}</option>
            </select>
          </div>
          <div className="space-y-1.5">
            <label className="block text-sm font-medium text-slate-700">{t("common.description")}</label>
            <textarea placeholder={t("common.description")} value={form.description} onChange={(e) => setForm({ ...form, description: e.target.value })} className={inputClass} rows={3} required />
          </div>
          <div className="flex flex-col-reverse gap-3 pt-1 sm:flex-row sm:justify-end">
            <button type="button" onClick={() => setShowForm(false)} className="rounded-lg border border-gray-300 px-4 py-2.5 text-sm font-medium text-gray-700 transition hover:bg-gray-50"><X size={16} className="ms-1 inline-block" />{t("common.cancel")}</button>
            <SubmitButton loading={saving} label={t("common.save")} loadingLabel={t("common.saving")} className="bg-blue-600 hover:bg-blue-700 text-white"><Save size={16} /></SubmitButton>
          </div>
        </form>
      </FormModal>

      <div className="rounded-2xl border border-slate-200 bg-white shadow-sm">
        <div className="flex flex-col gap-3 border-b border-slate-200 p-4 md:flex-row md:items-center md:flex-wrap">
          <div className="w-full md:w-80 md:flex-none"><SearchInput value={search} onChange={setSearchInput} placeholder={t("serviceRequests.searchPlaceholder")} /></div>
          <FilterSelect value={statusFilter} onChange={(v) => { setStatusFilter(v); setPage(1); }} options={Object.entries(STATUS_LABELS).map(([value, label]) => ({ value, label }))} allLabel={`${t("serviceRequests.status")} ΓÇö ${t("common.all")}`} className="md:w-40" />
          <FilterSelect value={priorityFilter} onChange={(v) => { setPriorityFilter(v); setPage(1); }} options={Object.entries(PRIORITY_LABELS).map(([value, label]) => ({ value, label }))} allLabel={`${t("serviceRequests.priorityFilter")} ΓÇö ${t("common.all")}`} className="md:w-36" />
          {!isEngineer && (
            <FilterSelect value={engineerFilter} onChange={(v) => { setEngineerFilter(v); setPage(1); }} options={engineers.map((e) => ({ value: e.id, label: e.name }))} allLabel={`${t("serviceRequests.engineerFilter")} ΓÇö ${t("common.all")}`} className="md:w-44" />
          )}
          <DateRangeFilter from={dateFrom} to={dateTo} onFromChange={(v) => { setDateFrom(v); setPage(1); }} onToChange={(v) => { setDateTo(v); setPage(1); }} />
          {hasActiveFilters && (
            <button onClick={() => { setSearchInput(null); setStatusFilter(""); setPriorityFilter(""); setEngineerFilter(""); setDateFrom(""); setDateTo(""); }} className="text-sm text-gray-500 hover:text-gray-700 underline">
              {t("common.resetFilters")}
            </button>
          )}
          <div className="md:ms-auto mt-2 md:mt-0">
            <ExportButton filename="service-requests" getExport={exportRequests} disabled={filtered.length === 0} />
          </div>
        </div>
        {loading ? (
          <div className="flex min-h-[320px] w-full items-center justify-center px-4 py-8">
            <PrinterLoader size="md" label={t("common.loading")} />
          </div>
        ) : requests.length === 0 ? (
          <div className="flex min-h-[200px] items-center justify-center">
            <p className="text-sm text-gray-400">{t("common.noData")}</p>
          </div>
        ) : filtered.length === 0 ? (
          <div className="flex min-h-[200px] items-center justify-center">
            <p className="text-sm text-gray-400">{t("common.noData")}</p>
          </div>
        ) : (
          <>
          <div className="overflow-x-auto">
            <table className="w-full min-w-[860px]">
              <thead className="bg-gray-50">
                <tr>
                  <th className="px-4 py-3 text-start text-sm font-medium text-gray-500">{t("serviceRequests.requestNumber")}</th>
                  <th className="px-4 py-3 text-start text-sm font-medium text-gray-500">{t("serviceRequests.customer")}</th>
                  <th className="px-4 py-3 text-start text-sm font-medium text-gray-500">{t("serviceRequests.machine")}</th>
                  <th className="px-4 py-3 text-start text-sm font-medium text-gray-500">{t("serviceRequests.priority")}</th>
                  <th className="px-4 py-3 text-start text-sm font-medium text-gray-500">{t("serviceRequests.status")}</th>
                  <th className="px-4 py-3 text-start text-sm font-medium text-gray-500">{t("serviceRequests.engineer")}</th>
                  <th className="px-4 py-3 text-start text-sm font-medium text-gray-500">{t("common.date")}</th>
                  <th className="px-4 py-3 text-start text-sm font-medium text-gray-500">{t("serviceRequests.problems")}</th>
                  <th className="px-4 py-3 text-start text-sm font-medium text-gray-500">{t("serviceRequests.rating")}</th>
                  <th className="px-4 py-3 text-start text-sm font-medium text-gray-500">{t("common.actions")}</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-gray-200">
                {paged.map((req) => (
                  <tr key={req.id} className="hover:bg-gray-50">
                    <td className="px-4 py-3 text-sm font-medium">{req.requestNumber}</td>
                    <td className="px-4 py-3 text-sm">
                      <Link href={`/customers?q=${encodeURIComponent(req.customer.name)}`} className="text-blue-600 hover:underline">
                        {req.customer.name}
                      </Link>
                    </td>
                    <td className="px-4 py-3 text-sm">
                      {req.machine ? (
                        <Link href={`/machines?serial=${encodeURIComponent(req.machine.serialNumber)}`} className="font-mono text-blue-600 hover:underline">
                          {req.machine.serialNumber}
                        </Link>
                      ) : "-"}
                    </td>
                    <td className="px-4 py-3">
                      <span className={`inline-flex px-2.5 py-0.5 rounded-full text-xs font-medium ${priorityColors[req.priority] || ""}`}>
                        {PRIORITY_LABELS[req.priority] || req.priority}
                      </span>
                    </td>
                    <td className="px-4 py-3">
                      <span className={`inline-flex px-2.5 py-0.5 rounded-full text-xs font-medium ${statusColors[req.status] || ""}`}>
                        {STATUS_LABELS[req.status] || req.status}
                      </span>
                    </td>
                    <td className="px-4 py-3 text-sm">{req.engineer?.name || "-"}</td>
                    <td className="px-4 py-3 text-sm"><DateTimeCell value={req.createdAt} /></td>
                    <td className="px-4 py-3 text-sm text-center">{req.problems.length}</td>
                    <td className="px-4 py-3 text-sm">{renderStars(req.customerRating)}</td>
                    <td className="px-4 py-3 text-sm">
                      <div className="flex gap-1 flex-wrap">
                        {canManageRequests && req.status !== "CLOSED" && req.status !== "RESOLVED" && req.status !== "NOT_RESOLVED" && (
                          <>
                            <button onClick={() => setAssigningId(assigningId === req.id ? null : req.id)} className="text-purple-600 hover:underline text-xs">
                              {t("serviceRequests.assign")}
                            </button>
                            <button onClick={() => handleStatus(req.id, "RESOLVED")} className="text-green-600 hover:underline text-xs">
                              {t("common.resolve")}
                            </button>
                            <button onClick={() => handleStatus(req.id, "NOT_RESOLVED")} className="text-red-600 hover:underline text-xs">
                              {t("common.notResolve")}
                            </button>
                          </>
                        )}

                        {isEngineer && req.engineerId === myEngineerId && req.status !== "CLOSED" && req.status !== "RESOLVED" && req.status !== "NOT_RESOLVED" && (
                          <>
                            <button onClick={() => handleStatus(req.id, "VISITED")} className="text-amber-600 hover:underline text-xs">
                              {t("serviceRequests.visited")}
                            </button>
                            <button onClick={() => handleStatus(req.id, "RESOLVED")} className="text-green-600 hover:underline text-xs">
                              {t("common.resolve")}
                            </button>
                            <button onClick={() => handleStatus(req.id, "NOT_RESOLVED")} className="text-red-600 hover:underline text-xs">
                              {t("common.notResolve")}
                            </button>
                          </>
                        )}

                        {(canManageRequests || (isEngineer && req.engineerId === myEngineerId)) && req.status === "RESOLVED" && (
                          <button onClick={() => handleStatus(req.id, "CLOSED")} className="text-gray-600 hover:underline text-xs">{t("serviceRequests.closed")}</button>
                        )}
                        {canManageRequests && (
                          <button onClick={() => handleDelete(req.id)} className="inline-flex items-center gap-1 rounded-lg border border-red-200 bg-red-50 px-2 py-1 text-xs font-medium text-red-600 transition hover:bg-red-100" title={t("common.delete")}>
                            <Trash2 size={12} />
                          </button>
                        )}
                      </div>
                      {assigningId === req.id && canManageRequests && (
                        <div className="mt-2 flex gap-1">
                          <select value={assignEngineerId} onChange={(e) => setAssignEngineerId(e.target.value)} className="rounded-lg border border-gray-300 px-2 py-1 text-xs focus:border-blue-500 focus:outline-none focus:ring-2 focus:ring-blue-500">
                            <option value="">{t("serviceRequests.selectEngineer")}</option>
                            {engineers.map((eng) => (<option key={eng.id} value={eng.id}>{eng.name}</option>))}
                          </select>
                          <button onClick={() => handleAssign(req.id)} className="bg-blue-600 text-white px-2 py-1 rounded text-xs hover:bg-blue-700">{t("serviceRequests.ok")}</button>
                        </div>
                      )}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
          <Pagination currentPage={safePage} totalPages={totalPages} onPageChange={setPage} totalItems={filtered.length} pageSize={PAGE_SIZE} />
          </>
        )}
      </div>
    </div>
  );
}

"use client";

import { useState, useEffect } from "react";
import { useI18n } from "@/i18n/context";
import { useSession } from "next-auth/react";
import SearchInput, { matchesQuery } from "@/components/SearchInput";
import FilterSelect from "@/components/FilterSelect";
import PrinterLoader from "@/components/PrinterLoader";
import { useConfirm } from "@/components/UIProvider";
import { apiErrorMessage } from "@/lib/api-client";
import { Plus, Pencil, Power, Eye, EyeOff, X, Trash2, Save } from "lucide-react";
import SubmitButton from "@/components/SubmitButton";
import { DateTimeCell } from "@/components/DateTimeCell";

interface User {
  id: string;
  name: string;
  email: string;
  role: string;
  companyId: string | null;
  isActive: boolean;
  createdAt: string;
}

const ROLE_BADGES: Record<string, string> = {
  GENERAL_MANAGER: "bg-purple-100 text-purple-800",
  COMPANY_MANAGER: "bg-blue-100 text-blue-800",
  ACCOUNTANT: "bg-green-100 text-green-800",
  MAINTENANCE_MANAGER: "bg-yellow-100 text-yellow-800",
  WORKSHOP_MANAGER: "bg-orange-100 text-orange-800",
  ENGINEER: "bg-cyan-100 text-cyan-800",
  SALES_EMPLOYEE: "bg-pink-100 text-pink-800",
};

const ALL_ROLES = Object.keys(ROLE_BADGES);

const emptyForm = {
  name: "",
  email: "",
  password: "",
  role: "SALES_EMPLOYEE",
  companyId: "",
};

export default function SettingsPage() {
  const { t, locale, dir } = useI18n();
  const confirmAction = useConfirm();

  const { data: session } = useSession();
  const meId = (session?.user as { id?: string })?.id;

  const [users, setUsers] = useState<User[]>([]);
  const [usersLoaded, setUsersLoaded] = useState(false);
  const loading = !usersLoaded;
  const [search, setSearch] = useState("");
  const [roleFilter, setRoleFilter] = useState("");
  const [banner, setBanner] = useState<{ type: "success" | "error"; text: string } | null>(null);

  const [modalOpen, setModalOpen] = useState(false);
  const [editingUser, setEditingUser] = useState<User | null>(null);
  const [form, setForm] = useState(emptyForm);
  const [showPassword, setShowPassword] = useState(false);
  const [saving, setSaving] = useState(false);
  const [formError, setFormError] = useState("");

  const fetchUsers = async () => {
    try {
      const res = await fetch("/api/users");
      const data = await res.json();
      if (res.ok) setUsers(Array.isArray(data) ? data : []);
    } finally {
      setUsersLoaded(true);
    }
  };

  useEffect(() => {
    if (usersLoaded) return;
    let cancelled = false;
    fetch("/api/users")
      .then((r) => r.json())
      .then((data) => {
        if (cancelled) return;
        setUsers(Array.isArray(data) ? data : []);
        setUsersLoaded(true);
      })
      .catch(() => {
        if (!cancelled) setUsersLoaded(true);
      });
    return () => {
      cancelled = true;
    };
  }, [usersLoaded]);

  const filteredUsers = users.filter(
    (user) =>
      (!roleFilter || user.role === roleFilter) &&
      (matchesQuery(user.name, search) ||
        matchesQuery(user.email, search) ||
        matchesQuery(t(`roles.${user.role}`), search))
  );

  const openCreate = () => {
    setEditingUser(null);
    setForm(emptyForm);
    setShowPassword(false);
    setFormError("");
    setModalOpen(true);
  };

  const openEdit = (user: User) => {
    setEditingUser(user);
    setForm({
      name: user.name,
      email: user.email,
      password: "",
      role: user.role,
      companyId: user.companyId || "",
    });
    setShowPassword(false);
    setFormError("");
    setModalOpen(true);
  };

  const handleSave = async (e: React.FormEvent) => {
    e.preventDefault();
    if (saving) return;
    setSaving(true);
    setFormError("");
    try {
      const isEdit = Boolean(editingUser);
      const payload: Record<string, unknown> = {
        name: form.name,
        email: form.email,
        role: form.role,
        companyId: form.companyId || null,
      };
      if (!isEdit || form.password !== "") payload.password = form.password;

      const res = await fetch(isEdit ? `/api/users/${editingUser!.id}` : "/api/users", {
        method: isEdit ? "PUT" : "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(payload),
      });
      const data = await res.json();

      if (!res.ok) {
        setFormError(apiErrorMessage(data, t, "settings.actionFailed"));
        return;
      }

      setModalOpen(false);
      await fetchUsers();
      setBanner({ type: "success", text: t(isEdit ? "settings.userUpdated" : "settings.userCreated") });
    } catch {
      setFormError(t("settings.actionFailed"));
    } finally {
      setSaving(false);
    }
  };

  const toggleStatus = async (user: User) => {
    if (
      !(await confirmAction({
        message: `${t("settings.toggleStatusConfirm")}\n${user.name} ΓÇö ${user.email}`,
      }))
    )
      return;
    try {
      const res = await fetch(`/api/users/${user.id}`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ isActive: !user.isActive }),
      });
      if (!res.ok) {
        const data = await res.json();
        setBanner({ type: "error", text: apiErrorMessage(data, t, "settings.actionFailed") });
        return;
      }
      setUsers((prev) => prev.map((u) => (u.id === user.id ? { ...u, isActive: !user.isActive } : u)));
      setBanner({ type: "success", text: t("settings.statusChanged") });
    } catch {
      setBanner({ type: "error", text: t("settings.actionFailed") });
    }
  };

  const handleDelete = async (user: User) => {
    if (user.id === meId) {
      setBanner({ type: "error", text: "┘ä╪º ┘è┘à┘â┘å┘â ╪¡╪░┘ü ╪¡╪│╪º╪¿┘â ╪º┘ä╪┤╪«╪╡┘è" });
      return;
    }

    if (!(await confirmAction({ message: `${t("common.deleteConfirm")}\n${user.name} ΓÇö ${user.email}` }))) {
      return;
    }

    try {
      const res = await fetch(`/api/users/${user.id}`, { method: "DELETE" });
      const data = await res.json().catch(() => null);

      if (!res.ok) {
        setBanner({
          type: "error",
          text: apiErrorMessage(data, t, "settings.actionFailed"),
        });
        return;
      }

      setUsers((prev) => prev.filter((u) => u.id !== user.id));
      setBanner({ type: "success", text: t("common.deletedSuccessfully") });
    } catch {
      setBanner({ type: "error", text: t("settings.actionFailed") });
    }
  };

  return (
    <div dir={dir}>
      <h1 className="text-xl sm:text-2xl font-bold mb-6">{t("users.title")}</h1>

      <div className="space-y-3">
          {banner && (
            <div
              className={`rounded-lg px-4 py-3 text-sm flex items-center justify-between ${
                banner.type === "success"
                  ? "bg-green-50 text-green-800 border border-green-200"
                  : "bg-red-50 text-red-800 border border-red-200"
              }`}
              role="status"
            >
              <span>{banner.text}</span>
              <button onClick={() => setBanner(null)} className="shrink-0 opacity-60 hover:opacity-100" aria-label="close">
                <X size={16} />
              </button>
            </div>
          )}

          <div className="bg-white rounded-xl shadow-md overflow-hidden">
            <div className="p-4 border-b flex flex-col gap-2 md:flex-row md:items-center md:flex-wrap">
              <SearchInput value={search} onChange={setSearch} placeholder={t("settings.usersSearchPlaceholder")} className="md:max-w-md" />
              <FilterSelect
                value={roleFilter}
                onChange={(v) => setRoleFilter(v)}
                options={ALL_ROLES.map((role) => ({ value: role, label: t(`roles.${role}`) }))}
                allLabel={`${t("settings.roleFilter")} ΓÇö ${t("common.all")}`}
                className="md:w-48"
              />
              {(search !== "" || roleFilter !== "") && (
                <button onClick={() => { setSearch(""); setRoleFilter(""); }} className="text-sm text-gray-500 hover:text-gray-700 underline">
                  {t("common.resetFilters")}
                </button>
              )}
              <button
                onClick={openCreate}
                className="md:ms-auto inline-flex items-center justify-center gap-2 rounded-lg bg-blue-600 px-4 py-2.5 text-sm font-medium text-white transition hover:bg-blue-700 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-blue-600"
              >
                <Plus size={18} />
                {t("settings.addUser")}
              </button>
            </div>

            {loading ? (
              <div className="flex items-center justify-center p-12">
                <PrinterLoader size="sm" label={t("common.loading")} />
              </div>
            ) : (
              <div className="overflow-x-auto">
                <table className="w-full min-w-[720px]">
                  <thead className="bg-gray-50">
                    <tr>
                      <th className="px-4 py-3 text-start text-sm font-medium text-gray-500">{t("settings.colUser")}</th>
                      <th className="px-4 py-3 text-start text-sm font-medium text-gray-500">{t("settings.colRole")}</th>
                      <th className="px-4 py-3 text-start text-sm font-medium text-gray-500">{t("settings.colStatus")}</th>
                      <th className="px-4 py-3 text-start text-sm font-medium text-gray-500">{t("common.date")}</th>
                      <th className="px-4 py-3 text-start text-sm font-medium text-gray-500 w-28">{t("common.actions") || ""}</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-gray-200">
                    {filteredUsers.map((user) => {
                      const isSelf = user.id === meId;
                      const initials = user.name.trim().slice(0, 2);
                      return (
                        <tr key={user.id} className={`hover:bg-gray-50 ${!user.isActive ? "opacity-60" : ""}`}>
                          <td className="px-4 py-3">
                            <div className="flex items-center gap-3">
                              <span className={`flex h-10 w-10 shrink-0 items-center justify-center rounded-full text-xs font-bold ${ROLE_BADGES[user.role] || "bg-gray-100 text-gray-700"}`}>
                                {initials}
                              </span>
                              <div className="min-w-0">
                                <p className="text-sm font-semibold text-gray-900 truncate">
                                  {user.name}
                                  {isSelf && (
                                    <span className="ms-2 rounded-full bg-blue-50 px-2 py-0.5 text-[11px] font-medium text-blue-700 align-middle">
                                      {t("settings.you")}
                                    </span>
                                  )}
                                </p>
                                <p className="text-xs text-gray-500 truncate" dir="ltr">{user.email}</p>
                              </div>
                            </div>
                          </td>
                          <td className="px-4 py-3">
                            <span className={`inline-flex whitespace-nowrap px-2.5 py-1 rounded-full text-xs font-medium ${ROLE_BADGES[user.role] || "bg-gray-100 text-gray-700"}`}>
                              {t(`roles.${user.role}`)}
                            </span>
                          </td>
                          <td className="px-4 py-3">
                            <span className={`inline-flex items-center gap-1.5 whitespace-nowrap rounded-full px-2.5 py-1 text-xs font-medium ${
                              user.isActive ? "bg-green-50 text-green-700" : "bg-gray-100 text-gray-500"
                            }`}>
                              <span className={`h-1.5 w-1.5 rounded-full ${user.isActive ? "bg-green-500" : "bg-gray-400"}`} />
                              {t(user.isActive ? "settings.active" : "settings.inactive")}
                            </span>
                          </td>
                          <td className="px-4 py-3 text-sm text-gray-600 whitespace-nowrap">
                            <DateTimeCell value={user.createdAt} />
                          </td>
                          <td className="px-4 py-3">
                            <div className="flex items-center gap-1">
                              <button
                                onClick={() => openEdit(user)}
                                title={t("settings.editUser")}
                                aria-label={t("settings.editUser")}
                                className="inline-flex h-9 w-9 items-center justify-center rounded-lg text-gray-500 transition hover:bg-blue-50 hover:text-blue-600"
                              >
                                <Pencil size={18} />
                              </button>
                              {!isSelf && (
                                <>
                                  <button
                                    onClick={() => toggleStatus(user)}
                                    title={t(user.isActive ? "settings.suspendAction" : "settings.activateAction")}
                                    aria-label={t(user.isActive ? "settings.suspendAction" : "settings.activateAction")}
                                    className={`inline-flex h-9 w-9 items-center justify-center rounded-lg transition ${
                                      user.isActive
                                        ? "text-gray-500 hover:bg-red-50 hover:text-red-600"
                                        : "text-gray-500 hover:bg-green-50 hover:text-green-600"
                                    }`}
                                  >
                                    <Power size={18} />
                                  </button>
                                  <button
                                    onClick={() => handleDelete(user)}
                                    title={t("common.delete")}
                                    aria-label={t("common.delete")}
                                    className="inline-flex h-9 w-9 items-center justify-center rounded-lg text-gray-500 transition hover:bg-red-50 hover:text-red-600"
                                  >
                                    <Trash2 size={18} />
                                  </button>
                                </>
                              )}
                            </div>
                          </td>
                        </tr>
                      );
                    })}
                    {filteredUsers.length === 0 && (
                      <tr>
                        <td colSpan={5} className="px-4 py-8 text-center text-gray-400">{t("common.noData")}</td>
                      </tr>
                    )}
                  </tbody>
                </table>
              </div>
            )}
          </div>
        </div>

      {modalOpen && (
        <div
          className="fixed inset-0 z-50 flex items-end sm:items-center justify-center bg-black/40 p-0 sm:p-4 cursor-pointer"
          role="dialog"
          aria-modal="true"
          onClick={(e) => { if (e.target === e.currentTarget) setModalOpen(false); }}
        >
          <form
            onSubmit={handleSave}
            className="w-full max-w-md rounded-t-2xl sm:rounded-2xl bg-white p-5 sm:p-6 shadow-xl max-h-[92vh] overflow-y-auto sidebar-scroll cursor-default"
          >
            <div className="mb-5 flex items-center justify-between">
              <h3 className="text-lg font-bold text-gray-900">
                {editingUser ? t("settings.editUser") : t("settings.newUser")}
              </h3>
              <button
                type="button"
                onClick={() => setModalOpen(false)}
                className="rounded-lg p-1.5 text-gray-400 hover:bg-gray-100 hover:text-gray-700"
                aria-label="close"
              >
                <X size={20} />
              </button>
            </div>

            <div className="space-y-4">
              <div>
                <label htmlFor="user-name" className="mb-1 block text-sm font-medium text-gray-700">{t("settings.fullName")}</label>
                <input
                  id="user-name"
                  type="text"
                  required
                  value={form.name}
                  onChange={(e) => setForm({ ...form, name: e.target.value })}
                  className="w-full rounded-lg border border-gray-300 px-3 py-2.5 text-sm focus:border-blue-500 focus:outline-none"
                  autoComplete="off"
                />
              </div>

              <div>
                <label htmlFor="user-email" className="mb-1 block text-sm font-medium text-gray-700">{t("customers.email")}</label>
                <input
                  id="user-email"
                  type="email"
                  required
                  dir="ltr"
                  value={form.email}
                  onChange={(e) => setForm({ ...form, email: e.target.value })}
                  disabled={Boolean(editingUser)}
                  className={`w-full rounded-lg border border-gray-300 px-3 py-2.5 text-sm focus:border-blue-500 focus:outline-none ${
                    editingUser ? "cursor-not-allowed bg-gray-100 text-gray-500" : ""
                  }`}
                  autoComplete="off"
                />
              </div>

              <div>
                <label htmlFor="user-password" className="mb-1 block text-sm font-medium text-gray-700">
                  {t("settings.password")}
                  {editingUser && <span className="block text-xs font-normal text-gray-400">{t("settings.passwordNewHint")}</span>}
                </label>
                <div className="relative">
                  <input
                    id="user-password"
                    type={showPassword ? "text" : "password"}
                    required={!editingUser}
                    minLength={editingUser ? undefined : 6}
                    dir="ltr"
                    value={form.password}
                    onChange={(e) => setForm({ ...form, password: e.target.value })}
                    className="w-full rounded-lg border border-gray-300 px-3 py-2.5 pr-10 text-sm focus:border-blue-500 focus:outline-none"
                    autoComplete="new-password"
                    placeholder={editingUser ? "ΓÇóΓÇóΓÇóΓÇóΓÇóΓÇóΓÇóΓÇó" : ""}
                  />
                  <button
                    type="button"
                    onClick={() => setShowPassword(!showPassword)}
                    title={t(showPassword ? "settings.hidePassword" : "settings.showPassword")}
                    aria-label={t(showPassword ? "settings.hidePassword" : "settings.showPassword")}
                    className="absolute inset-y-0 right-0 flex items-center px-3 text-gray-400 hover:text-gray-600"
                  >
                    {showPassword ? <EyeOff size={17} /> : <Eye size={17} />}
                  </button>
                </div>
                {!editingUser && <p className="mt-1 text-xs text-gray-400">{t("settings.passwordMin")}</p>}
              </div>

              <div>
                <label htmlFor="user-role" className="mb-1 block text-sm font-medium text-gray-700">{t("settings.colRole")}</label>
                <select
                  id="user-role"
                  value={form.role}
                  onChange={(e) => setForm({ ...form, role: e.target.value })}
                  disabled={Boolean(editingUser) && editingUser!.id === meId}
                  className="w-full rounded-lg border border-gray-300 bg-white px-3 py-2.5 text-sm focus:border-blue-500 focus:outline-none disabled:cursor-not-allowed disabled:bg-gray-100"
                >
                  {ALL_ROLES.map((role) => (
                    <option key={role} value={role}>{t(`roles.${role}`)}</option>
                  ))}
                </select>
              </div>
            </div>

            {formError && (
              <div className="mt-4 rounded-lg border border-red-200 bg-red-50 px-3 py-2.5 text-sm text-red-700" role="alert">
                {formError}
              </div>
            )}

            <div className="mt-6 flex flex-col-reverse gap-2 sm:flex-row sm:justify-end">
              <button
                type="button"
                onClick={() => setModalOpen(false)}
                className="rounded-lg border border-gray-300 px-4 py-2.5 text-sm font-medium text-gray-700 transition hover:bg-gray-50"
              >
                {t("common.cancel")}
              </button>
              <SubmitButton loading={saving} label={t("common.save")} loadingLabel={t("common.saving")} className="bg-blue-600 hover:bg-blue-700 text-white"><Save size={16} /></SubmitButton>
            </div>
          </form>
        </div>
      )}
    </div>
  );
}

