    const { id } = await params;
    const engineer = await prisma.engineer.findUnique({
      where: { id },
      include: {
        areas: true,
        skills: true,
        serviceRequests: {
          include: { customer: { select: { id: true, name: true } } },
          orderBy: { createdAt: "desc" },
        },
        visits: {
          include: { serviceRequest: { select: { requestNumber: true } } },
