        }
        const taken = await prisma.engineer.findUnique({ where: { userId: linkedUser.id } });
        if (taken && taken.id !== id) {
          return NextResponse.json({ error: "┘ç╪░╪º ╪º┘ä╪¡╪│╪º╪¿ ┘à╪▒╪¬╪¿╪╖ ╪¿┘à┘ç┘å╪»╪│ ╪ó╪«╪▒" }, { status: 409 });
        }
        userId = linkedUser.id;
