    }
    if (data.priority && !["NORMAL", "IMPORTANT", "URGENT", "EMERGENCY"].includes(data.priority)) {
      return NextResponse.json({ error: "┘é┘è┘à╪⌐ ╪º┘ä╪ú┘ê┘ä┘ê┘è╪⌐ ╪║┘è╪▒ ╪╡╪º┘ä╪¡╪⌐", code: "INVALID_PRIORITY" }, { status: 400 });
    }
    if (data.machineId) {
      const machine = await prisma.machine.findUnique({ where: { id: data.machineId }, select: { id: true } });
      if (!machine) {
        return NextResponse.json({ error: "╪º┘ä╪¼┘ç╪º╪▓ ╪║┘è╪▒ ┘à┘ê╪¼┘ê╪»", code: "MACHINE_NOT_FOUND" }, { status: 400 });
      }
