      if (!location) {
        return NextResponse.json({ error: "╪º┘ä┘à┘ê┘é╪╣ ╪║┘è╪▒ ┘à┘ê╪¼┘ê╪»", code: "LOCATION_NOT_FOUND" }, { status: 400 });
