        );
      }
      if (existing.status === "VERIFIED") {
        return NextResponse.json({ error: "╪º┘ä╪¬╪│┘ê┘è╪⌐ ╪¬┘à ╪º┘ä╪¬╪¡┘é┘é ┘à┘å┘ç╪º ╪¿╪º┘ä┘ü╪╣┘ä", code: "ALREADY_VERIFIED" }, { status: 409 });
      }
    } else if (body.status && body.status !== "INITIAL") {
      return NextResponse.json({ error: "╪¡╪º┘ä╪⌐ ╪║┘è╪▒ ╪╡╪º┘ä╪¡╪⌐", code: "INVALID_STATUS" }, { status: 400 });
    }

    const data: Record<string, unknown> = {};
    if ("status" in body) data.status = body.status;
    if ("reason" in body && !body.status) data.reason = body.reason;
    if (body.status === "VERIFIED") data.verifiedBy = actor.id;

    if (Object.keys(data).length === 0) {
      return NextResponse.json({ error: "┘ä╪º ╪¬┘ê╪¼╪» ╪¿┘è╪º┘å╪º╪¬ ┘ä┘ä╪¬╪¡╪»┘è╪½", code: "NO_CHANGES" }, { status: 400 });
